// String collection
IList<string> stringList = new List<string>() {
    "C# Tutorials",
    "VB.NET Tutorials",
    "Learn C++",
    "MVC Tutorials",
    "Java"
};

// LINQ Method Syntax
var result = stringList.Where(s => s.Contains("Tutorials"));

// Result: "C# Tutorials", "VB.NET Tutorials", "MVC Tutorials"

// The Where method signature:
// IEnumerable<TSource> Where<TSource>(this IEnumerable<TSource> source, Func<TSource, bool> predicate)

// The lambda expression 's => s.Contains("Tutorials")' matches Func<string, bool>
var result = stringList.Where(s => s.Contains("Tutorials"));

// Student collection
IList<Student> studentList = new List<Student>() {
    new Student() { StudentID = 1, StudentName = "John", Age = 13 },
    new Student() { StudentID = 2, StudentName = "Moin", Age = 21 },
    new Student() { StudentID = 3, StudentName = "Bill", Age = 18 },
    new Student() { StudentID = 4, StudentName = "Ram", Age = 20 },
    new Student() { StudentID = 5, StudentName = "Ron", Age = 15 }
};

// LINQ Method Syntax to find teenager students
var teenAgerStudents = studentList.Where(s => s.Age > 12 && s.Age < 20)
                                  .ToList<Student>();

// Chain Where, OrderBy, and Select
var result = studentList
    .Where(s => s.Age > 12 && s.Age < 20)
    .OrderBy(s => s.StudentName)
    .Select(s => s.StudentName)
    .ToList();
